# -*- coding: utf-8 -*-
# Обновление системного промта kip8test до post-Task 313
# (подсветка сегодняшней даты в шахматке + отдельное окно
#  «Мероприятия в этот день» НАД окном кодов)
with open('Системный_промт_для_приложения_КИПиА.md', encoding='utf-8') as f:
    lines = f.readlines()

new3 = '''> **Версия документа:** 2026-09-04 (post-Task 313: ПОДСВЕТКА СЕГОДНЯШНЕЙ ДАТЫ В ШАХМАТКЕ + ОТДЕЛЬНОЕ ОКНО «МЕРОПРИЯТИЯ В ЭТОТ ДЕНЬ» НАД ОКНОМ КОДОВ. Заявка пользователя: «В шахматке должен немного подсвечиваться фон сегодняшней даты. При нажатии на ячейку в шахматке, помимо окна с кодами, должно появляться ещё одно отдельное окно, расположенное над окном с кодами, в котором должны отображаться все мероприятия в этой ячейке, с отображением цвета, кода и названием, а в окне с кодами убери строку "Мероприятия в этот день", теперь этот функционал будет в окне выше, которое как раз можно назвать "Мероприятия в этот день"». СОДЕРЖАНИЕ: 1) ПОДСВЕТКА «СЕГОДНЯ»: _renderGrid кэширует this._todayIso (пересчёт на каждой отрисовке); шапка — класс ws-today-col (градиент ПОВЕРХ непрозрачного фона th: sticky-строка обязана оставаться непрозрачной; число — акцентом; правило ПОСЛЕ .ws-holiday — приоритет и на «сегодня-выходном»); ячейки — _renderCell даёт ws-today (isoDate === _todayIso), тонировка inset-«заливкой» box-shadow: inset 0 0 0 999px rgba(74,143,199,0.16) — рисуется ПОВЕРХ inline-цветов статусов и ПОД текстом; псевдоэлементы не заняты (::before — рамка д/н Task 309, ::after — точка переработки Task 250); «сегодня + ручная запись» — составное правило .ws-today.ws-source-manual (обе inset-тени); светлая тема мягче (42,93,143); видна и зрителям. 2) ОКНО МЕРОПРИЯТИЙ: НОВЫЙ #wsEventsPopup (.ws-cell-popup.ws-events-popup, role=dialog) в HTML после #wsCellPopup: max-height 300px, z-index 9402 (окно кодов 9401, кловер 9400 — при тесном вьюпорте окно мероприятий сверху, порядок «над окном кодов» не нарушается); НОВЫЙ _renderEventsPopup(isoDate, tabNo): заголовок «Мероприятия в этот день» + подстрока «дата · ФИО», строки мероприятий (свотч ЦВЕТА + КОД + НАЗВАНИЕ: тема из «Инструктажи», иначе название кода), кнопки ✎/✕ — только редакторам (Task 309, stopPropagation), пустой день — курсив «нет мероприятий» (окно открывается ВСЕГДА вместе с окном кодов); _renderCellPopup: секция «Мероприятия в этот день» УДАЛЕНА (строки-события и _eventsAt из окна кодов ушли; «+ Мероприятие…»/«Дополнительно…» живы); _openCellPopup: рендерит ОБА окна, окно мероприятий СТРОГО НАД окном кодов (левые края выровнены, зазор 8px, eTop = top - eh - 8; не влезает сверху — окно кодов сдвигается вниз, окна НЕ меняются местами; тесный вьюпорт — окно мероприятий прижимается к верху); closeCellPopup закрывает ОБА окна (один жизненный цикл: кловер, Esc, выбор статуса, «+ Мероприятие…», «Дополнительно…», editTraining/deleteTraining, клик по ФИО). Слой событий прежний (_eventsAt, лист «Инструктажи»); СЕРВЕР и листы НЕ менялись. Тесты: 1528 → 1546/0 (+18 test-task313.js; актуализированы test-task312 [секция переехала]/test-work-events/test-task309; SW-бамп v551→v552 в 13 тест-файлах). Верификация: task313-browser-check.py 30/30 (3 контекста, порт 8937: геометрия «над окном кодов», содержимое, закрытие обоих окон, подсветка сегодня в тёмной/светлой темах, мобильный 375px, зритель); регресс task298 33/33, 303 20/20, 304 10/10, 305 20/20, 306 29/29, 307 20/20, 308 20/20, 309 26/26, 310 20/20, 311 24/24, 312 31/31 (актуализированы под Task 313); VLM ×4. СЕРВЕР и листы НЕ менялись. ПЕРЕНОС В kip8: НЕ выполнен (вместе с Task 312 ожидает проверки пользователем в kip8test; следующий шаг — перенос 312+313). Деплой пользователя: GitHub Pages + Ctrl+Shift+R ×1–2; Apps Script НЕ трогать.)
'''

assert lines[2].startswith('> **Версия документа:**')
lines.insert(2, new3 if new3.endswith('\n') else new3 + '\n')
prev = [i for i, l in enumerate(lines[:40]) if l.startswith('> **Версия документа (предыдущая):**')]
while len(prev) > 12:
    del lines[prev[-1]]
    prev = [i for i, l in enumerate(lines[:40]) if l.startswith('> **Версия документа (предыдущая):**')]
print('Строка 3 вставлена; цепочка «предыдущих»:', len(prev))

src = ''.join(lines)

reps = [
    ('> **Текущая версия кэша:** `kipia-test-v551`',
     '> **Текущая версия кэша:** `kipia-test-v553`'),
    ('| `kip8test` | PWA | `kipia-test-v551` |',
     '| `kip8test` | PWA | `kipia-test-v553` |'),
]
for old, new in reps:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Версии кэша обновлены (2 замены)')

# Счётчики тестов
reps2 = [
    ('├── tests/                      # 1528 юнит-тестов (Node.js, 30 файлов)',
     '├── tests/                      # 1546 юнит-тестов (Node.js, 31 файлов)'),
    ('ожидается `1528 passed, 0 failed`', 'ожидается `1546 passed, 0 failed`'),
    ('# Ожидается: 1528 passed, 0 failed', '# Ожидается: 1546 passed, 0 failed'),
]
for old, new in reps2:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Счётчики тестов обновлены (3 замены)')

# Аннотация Task 251: над окном кодов — окно мероприятий (Task 313)
old251 = 'Task 312: строка «— выходной —» УДАЛЕНА из попапа (очистка — в «Дополнительно…») и коды мероприятий не предлагаются (только статусы из листа); «Дополнительно…» открывает прежний sheet'
new251 = 'Task 312: строка «— выходной —» УДАЛЕНА из попапа (очистка — в «Дополнительно…») и коды мероприятий не предлагаются (только статусы из листа); Task 313: над окном кодов открывается ОТДЕЛЬНОЕ окно «Мероприятия в этот день» (события ячейки: цвет/код/название, ✎/✕) + колонка сегодняшней даты слегка подсвечена (ws-today-col/ws-today); «Дополнительно…» открывает прежний sheet'
assert old251 in src
src = src.replace(old251, new251)
print('Аннотация Task 251 (окно мероприятий над окном кодов) обновлена')

# Аннотация в буллете Task 312: секция переехала (Task 313)
old312b = 'событие видно в секции «Мероприятия в этот день» (с кнопками ✎/✕, Task 309)'
new312b = 'событие видно в секции «Мероприятия в этот день» (с кнопками ✎/✕, Task 309; Task 313: секция переехала в отдельное окно #wsEventsPopup НАД окном кодов)'
assert old312b in src
src = src.replace(old312b, new312b)
print('Аннотация Task 312 (секция переехала) обновлена')

entry = ('\n- **График работы — подсветка сегодняшней даты, окно «Мероприятия в этот день» над окном кодов (Task 313)**: '
         'по заявке пользователя: 1) ПОДСВЕТКА «СЕГОДНЯ»: _renderGrid кэширует this._todayIso (ISO сегодня, пересчёт на каждой отрисовке — ячейки не зовут new Date()); шапка: колонка сегодняшней даты — класс ws-today-col (.ws-grid thead th.ws-day-col.ws-today-col: linear-gradient ПОВЕРХ непрозрачного фона th — sticky-строка обязана оставаться непрозрачной; число даты — акцентом; правило ПОСЛЕ .ws-holiday — приоритет и на «сегодня-выходном»); ячейки: _renderCell даёт класс ws-today (isoDate === this._todayIso), тонировка — inset-«заливка» box-shadow: inset 0 0 0 999px rgba(74,143,199,0.16): рисуется ПОВЕРХ inline-цветов статусов (CSS-фон их не перекрывает) и ПОД текстом; псевдоэлементы не заняты (::before — рамка ручных д/н Task 309, ::after — точка переработки Task 250); совпадение «сегодня + ручная запись» — составное правило .ws-today.ws-source-manual (обе inset-тени в одном box-shadow); светлая тема мягче: шапка rgba(42,93,143,0.13), ячейки rgba(42,93,143,0.10); подсветка видна и зрителям (права не нужны). '
         '2) ОКНО МЕРОПРИЯТИЙ НАД ОКНОМ КОДОВ: НОВЫЙ контейнер #wsEventsPopup (.ws-cell-popup.ws-events-popup, role=dialog) в HTML сразу после #wsCellPopup — база .ws-cell-popup (фон/рамка/скролл), своё: max-height 300px и z-index 9402 (окно кодов 9401, кловер 9400: при тесном вьюпорте окно мероприятий остаётся сверху — порядок «над окном кодов» не нарушается); НОВЫЙ метод _renderEventsPopup(isoDate, tabNo): заголовок «Мероприятия в этот день» + подстрока «дата · ФИО» (контекст, если вьюпорт развёл окна), строки мероприятий — свотч ЦВЕТА + КОД + НАЗВАНИЕ (тема из листа «Инструктажи», иначе название кода), кнопки ✎/✕ — только редакторам (Task 309, stopPropagation), пустой день — курсив «нет мероприятий» (окно открывается ВСЕГДА вместе с окном кодов — поведение предсказуемо); _renderCellPopup: секция «Мероприятия в этот день» УДАЛЕНА из окна кодов (строки-события и сбор _eventsAt ушли; «+ Мероприятие…» и «Дополнительно…» — живы); _openCellPopup: рендерит ОБА окна, окно мероприятий позиционируется СТРОГО НАД окном кодов — левые края выровнены, зазор 8px (eTop = top - eh - 8), не влезает сверху — окно кодов сдвигается вниз (низ прижимается к краю вьюпорта, окна НЕ меняются местами), тесный вьюпорт — окно мероприятий прижимается к верху; closeCellPopup закрывает ОБА окна (один жизненный цикл: кловер, Esc, выбор статуса, «+ Мероприятие…», «Дополнительно…», editTraining/deleteTraining, клик по ФИО сотрудника). Слой событий прежний (_eventsAt, лист «Инструктажи»). '
         'Сервер WorkSchedule.gs/листы/«Сформировать» — НЕ менялись; бейджи (Task 303/305), рамка д/н (Task 309/310), попап статусов (Task 312), карточка сотрудника (Task 309/312) — живы. Верификация: сьют 1528→1546/0 (+18 tests/test-task313.js; актуализированы test-task312 [секция переехала]/test-work-events/test-task309; SW-бамп v551→v552 в 13 тест-файлах), task313-browser-check.py 30/30 (порт 8937, 3 контекста: геометрия «над окном кодов» [зазор 4–12px, левые края ±1px, z-index], содержимое [заголовок/подстрока/строки/пустое состояние], закрытие обоих окон [Esc/кловер], подсветка «сегодня» [одна колонка, computed-стили тёмной/светлой тем, инлайн-фон статуса жив, две inset-тени ручной записи], мобильный 375px, зритель — без окон но с подсветкой); регресс 298 33/33, 303 20/20, 304 10/10, 305 20/20, 306 29/29, 307 20/20, 308 20/20, 309 26/26, 310 20/20, 311 24/24, 312 31/31 (актуализированы под Task 313), VLM ×4. SW kipia-test-v551→v552. ДЕПЛОЙ: только фронтенд — GitHub Pages + Ctrl+Shift+R ×1–2; Apps Script НЕ трогать — см. scripts/DEPLOY-Task313-today-highlight-events-window.md')
lines2 = src.split('\n')
insert_at = None
for i, l in enumerate(lines2):
    if l.startswith('- **График работы — «+ Отпуск» в карточке сотрудника'):
        j = i + 1
        while j < len(lines2) and lines2[j].startswith('  '):
            j += 1
        insert_at = j
        break
assert insert_at is not None, 'точка вставки (после буллета Task 312) не найдена'
lines2.insert(insert_at, entry)
src = '\n'.join(lines2)

with open('Системный_промт_для_приложения_КИПиА.md', 'w', encoding='utf-8') as f:
    f.write(src)
print('Промт обновлён до post-Task 313: строка версии, цепочка, кэш v552, счётчики 1546/31, аннотации 251/312, буллет Task 313')
